{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket does not block public access",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The bucket has no S3 Public Access Block, allowing a future ACL or bucket policy change to expose dashboard content publicly."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "Without versioning, overwritten or maliciously deleted dashboard objects cannot be recovered from prior versions."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 server access logging is disabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The bucket does not record access requests, reducing the available evidence for detecting and investigating unauthorized access."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket lacks KMS default encryption",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The bucket has no explicit customer-managed KMS encryption configuration, limiting control over key rotation, access, and auditing."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "admin_dashboard" {
  bucket = "smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_kms_key" "admin_dashboard" {
  description         = "KMS key for the admin dashboard S3 bucket"
  enable_key_rotation = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "admin_dashboard" {
  bucket = aws_s3_bucket.admin_dashboard.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.admin_dashboard.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket" "access_logs" {
  bucket = "smart-city-parking-management-system-s3-admin-dashboard-logs-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServerAccessLogs"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.access_logs.arn}/admin-dashboard/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.admin_dashboard.arn
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "admin_dashboard" {
  bucket        = aws_s3_bucket.admin_dashboard.id
  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = "admin-dashboard/"

  depends_on = [aws_s3_bucket_policy.access_logs]
}
",
  "fix_summary": "Added public-access blocking, versioning, and customer-managed KMS encryption with key rotation for the dashboard bucket. Added a private, encrypted, versioned destination bucket and enabled S3 server access logging."
}
